package dashboard.enterprise.agent.llm.resolution;import dashboard.enterprise.agent.llm.model.LlmRequest;import dashboard.enterprise.agent.llm.provider.LlmProvider;import dashboard.enterprise.agent.llm.registry.LlmProviderRegistry;import java.util.Comparator;public final class LlmProviderResolver{private final LlmProviderRegistry registry;public LlmProviderResolver(LlmProviderRegistry r){registry=r;}public LlmProvider resolve(LlmRequest req){if(!req.preferredProviderId().isBlank()){LlmProvider p=registry.require(req.preferredProviderId());if(!p.available())throw new IllegalStateException("Preferred LLM provider is unavailable: "+p.providerId());if(!p.supports(req.capabilityId()))throw new IllegalArgumentException("Preferred LLM provider does not support capability: "+req.capabilityId());return p;}return registry.all().stream().filter(LlmProvider::available).filter(p->p.supports(req.capabilityId())).sorted(Comparator.comparingInt(LlmProvider::priority).reversed().thenComparing(LlmProvider::providerId)).findFirst().orElseThrow(()->new IllegalArgumentException("No available LLM provider supports capability: "+req.capabilityId()));}}
